from copy import deepcopy


def parse_cards(source):
    if not isinstance(source, str):
        raise TypeError("source must be a string")
    if not source.strip():
        return []

    result = []
    for block in source.strip().split("\n\n"):
        lines = [line.strip() for line in block.splitlines() if line.strip()]
        if len(lines) < 4 or not lines[0].startswith("Q: ") or not lines[-1].startswith("A: "):
            raise ValueError("malformed card")
        question = lines[0][3:].strip()
        option_lines = lines[1:-1]
        if not question or len(option_lines) < 2 or any(not line.startswith("- ") for line in option_lines):
            raise ValueError("malformed card")
        options = [line[2:].strip() for line in option_lines]
        if any(not option for option in options):
            raise ValueError("empty option")
        try:
            answer_number = int(lines[-1][3:].strip())
        except ValueError as exc:
            raise ValueError("answer must be an integer") from exc
        if not 1 <= answer_number <= len(options):
            raise ValueError("answer out of range")
        result.append({
            "question": question,
            "options": options,
            "answer": options[answer_number],
        })
    return result


def _validate_cards(cards):
    if not isinstance(cards, list):
        raise TypeError("cards must be a list")
    for card in cards:
        if not isinstance(card, dict) or set(card) != {"question", "options", "answer"}:
            raise ValueError("invalid card shape")
        if not isinstance(card["question"], str) or not card["question"]:
            raise ValueError("invalid question")
        if not isinstance(card["answer"], str) or not card["answer"]:
            raise ValueError("invalid answer")
        if not isinstance(card["options"], list) or any(
            not isinstance(option, str) or not option for option in card["options"]
        ):
            raise ValueError("invalid options")


def save_cards(cards, add_many):
    _validate_cards(cards)
    if not callable(add_many):
        raise TypeError("add_many must be callable")
    return add_many(deepcopy(cards))

